class BookCreateSerializer(serializers.ModelSerializer):
    class Meta:
        model = Book
        fields = ["id", "title", "author", "isbn", "price"]

    def to_internal_value(self, data):
        # نرمال‌سازی قبل از اعتبارسنجی
        if isinstance(data, dict):
            data = data.copy()
            if "title" in data and isinstance(data["title"], str):
                data["title"] = data["title"].strip()
            if "isbn" in data and isinstance(data["isbn"], str):
                data["isbn"] = data["isbn"].replace("-", "").strip()
        return super().to_internal_value(data)

class OrderSerializer(serializers.ModelSerializer):
    items = OrderItemSerializer(many=True)

    class Meta:
        model = Order
        fields = ["id", "customer", "items", "status", "created_at"]
        read_only_fields = ["id", "created_at"]

    def create(self, validated_data):
        items_data = validated_data.pop("items")
        order = Order.objects.create(**validated_data)
        OrderItem.objects.bulk_create([
            OrderItem(order=order, **item) for item in items_data
        ])
        return order

    def update(self, instance, validated_data):
        items_data = validated_data.pop("items", None)

        for attr, value in validated_data.items():
            setattr(instance, attr, value)
        instance.save()

        if items_data is not None:
            instance.items.all().delete()
            OrderItem.objects.bulk_create([
                OrderItem(order=instance, **item) for item in items_data
            ])
        return instance

class BookListSerializer(serializers.ListSerializer):
    def create(self, validated_data):
        books = [Book(**item) for item in validated_data]
        return Book.objects.bulk_create(books)

    def update(self, instance, validated_data):
        # instance: QuerySet از Bookها
        book_mapping = {book.id: book for book in instance}
        updated = []
        for item in validated_data:
            book = book_mapping.get(item.get("id"))
            if book:
                for attr, value in item.items():
                    setattr(book, attr, value)
                updated.append(book)
        Book.objects.bulk_update(updated, ["title", "price"])
        return updated


