class TemperatureSerializer(serializers.BaseSerializer):
    """تبدیل بین سلسیوس و فارنهایت."""

    def to_representation(self, instance):
        # instance: عدد سلسیوس
        return {
            "celsius": instance,
            "fahrenheit": round(instance * 9 / 5 + 32, 1),
        }

    def to_internal_value(self, data):
        if "celsius" not in data:
            raise serializers.ValidationError({"celsius": "الزامی است."})
        try:
            value = float(data["celsius"])
        except (TypeError, ValueError):
            raise serializers.ValidationError({"celsius": "عدد نامعتبر."})
        if value < -273.15:
            raise serializers.ValidationError({"celsius": "کمتر از صفر مطلق."})
        return value

class DynamicFieldsModelSerializer(serializers.ModelSerializer):
    def __init__(self, *args, **kwargs):
        fields = kwargs.pop("fields", None)
        super().__init__(*args, **kwargs)
        if fields is not None:
            allowed = set(fields)
            existing = set(self.fields)
            for field_name in existing - allowed:
                self.fields.pop(field_name)


